  // THEME: Human Rights & Citizenship
  '7': {
    easy: [
      {audio:"Every person has the right to education.",q:"What right does every person have?",opts:["Right to drive","Right to education","Right to vote at any age","Right to travel freely"],ans:1},
      {audio:"Citizens must follow the laws of their country.",q:"What must citizens follow?",opts:["Only school rules","The laws of their country","Only traffic rules","Only religious rules"],ans:1},
      {audio:"Freedom of speech is a fundamental right.",q:"What kind of right is freedom of speech?",opts:["A local right","A temporary right","A fundamental right","A special right"],ans:2},
      {audio:"We must respect people of all religions.",q:"Which people must we respect?",opts:["Only our religion","People of all religions","Only older people","Only wealthy people"],ans:1},
      {audio:"Equality means treating every person fairly.",q:"What does equality mean?",opts:["Giving more to the rich","Treating every person fairly","Rewarding hard workers only","Ignoring everyone"],ans:1},
      {audio:"Everyone has the right to work.",q:"What is a fundamental right?",opts:["Right to earn money only","Right to work","Right to be rich","Right to be lazy"],ans:1},
      {audio:"Children have the right to safe childhood.",q:"What do children have the right to?",opts:["Work all day","A safe childhood","Limited education","No protection"],ans:1},
      {audio:"The right to life is protected by law.",q:"Which right is protected?",opts:["Right to be rich","Right to life","Right to own everything","Right to hurt others"],ans:1},
      {audio:"We have freedom to express our opinions.",q:"What is freedom of expression?",opts:["Right to shout","Right to express opinions","Right to hurt others","Right to lie"],ans:1},
      {audio:"Discrimination is treating people unfairly.",q:"What is discrimination?",opts:["Fair treatment","Treating people unfairly","Helping others","Being kind"],ans:1}
    ],
    medium: [
      {audio:"The right to equality ensures no citizen is discriminated against by the state.",q:"What does the right to equality ensure?",opts:["Equal pay for all","No citizen is discriminated against by the state","All citizens live in same houses","Citizens can do anything"],ans:1},
      {audio:"Child labour robs children of their education and right to a safe childhood.",q:"What does child labour rob children of?",opts:["Toys and games","Education and right to a safe childhood","Food and shelter","Friends and family"],ans:1},
      {audio:"Citizens have both rights and duties towards their country and its people.",q:"What do citizens have besides rights?",opts:["Only privileges","Only freedoms","Duties towards their country and people","Responsibilities only to themselves"],ans:2},
      {audio:"The right to information allows citizens to question government decisions and actions.",q:"What does the right to information allow citizens to do?",opts:["Change laws freely","Question government decisions and actions","Avoid paying taxes","Travel without documents"],ans:1},
      {audio:"A truly democratic society protects the rights of its minorities and marginalised communities.",q:"Whose rights does a democratic society protect?",opts:["Only the majority","Only the government","Minorities and marginalised communities","Only wealthy citizens"],ans:2},
      {audio:"The right to privacy protects our personal information from being exposed.",q:"What does right to privacy protect?",opts:["Our money","Our personal information","Our reputation only","Our secrets"],ans:1},
      {audio:"Freedom of movement allows citizens to travel freely within their country.",q:"What does freedom of movement allow?",opts:["Flying in air","Traveling freely within the country","Moving to other planets","Teleportation"],ans:1},
      {audio:"The right to assembly allows people to gather peacefully for a cause.",q:"What does right to assembly allow?",opts:["Making weapons","Gathering peacefully","Creating violence","Harming others"],ans:1},
      {audio:"Press freedom allows newspapers to report on government actions.",q:"What does press freedom allow?",opts:["Creating lies","Reporting on government actions","Hiding truth","Spreading misinformation"],ans:1},
      {audio:"Duties remind us that freedom comes with responsibility.",q:"What do duties remind us about?",opts:["Making money","Freedom with responsibility","Being lazy","Having no responsibilities"],ans:1}
    ],
    hard: [
      {audio:"The Universal Declaration of Human Rights was adopted by the United Nations in nineteen forty-eight.",q:"When was the Universal Declaration of Human Rights adopted?",opts:["1945","1946","1947","1948"],ans:3},
      {audio:"Fundamental duties remind citizens that rights come with corresponding responsibilities to society.",q:"What do fundamental duties remind citizens about?",opts:["How to vote","Rights come with responsibilities to society","How to pay taxes","How to serve in military"],ans:1},
      {audio:"Gender equality remains a significant challenge in many parts of the world despite legislative progress.",q:"Despite what progress does gender inequality persist?",opts:["Economic progress","Technological progress","Legislative progress","Military progress"],ans:2},
      {audio:"Civic participation through voting and peaceful protest strengthens the foundations of democracy.",q:"What strengthens the foundations of democracy?",opts:["Military power only","Economic growth only","Civic participation through voting and peaceful protest","Written constitutions only"],ans:2},
      {audio:"The judiciary acts as a guardian of the constitution and protects citizens from state overreach.",q:"What is the judiciary's role regarding the constitution?",opts:["To write the constitution","To change the constitution","To act as its guardian","To ignore the constitution"],ans:2},
      {audio:"Social justice movements have fought for the rights of marginalized communities for decades.",q:"What have social justice movements fought for?",opts:["Only power","Rights of marginalized communities","Only money","Only fame"],ans:1},
      {audio:"Affirmative action policies aim to provide equal opportunities to disadvantaged groups.",q:"What do affirmative action policies aim for?",opts:["More inequality","Equal opportunities to disadvantaged groups","More advantages for rich","Removing all protections"],ans:1},
      {audio:"The convention on the rights of the child protects children from exploitation.",q:"What does the convention protect children from?",opts:["Education","Going to school","Exploitation","Playing"],ans:2},
      {audio:"Restorative justice focuses on rehabilitation rather than just punishment of offenders.",q:"What does restorative justice focus on?",opts:["Only punishment","Revenge on criminals","Rehabilitation of offenders","Ignoring crime"],ans:2},
      {audio:"International law seeks to protect human rights across all nations and borders.",q:"What does international law seek to protect?",opts:["Only national interests","Military superiority","Human rights across nations","Trade advantages only"],ans:2}
    ]
  },

